local({
  value <- coalesce(
    recode_values(as.numeric(haven::zap_labels(jq3)), 1 ~ "Male", 2 ~ "Female"),
    recode_values(as.character(sex), "male" ~ "Male", "female" ~ "Female", "other" ~ "Other")
  )
  coalesce(modal_within(value, participant_id), "Unknown")
})

local({
  level <- as.numeric(haven::zap_labels(schoollevel))
  case_when(
    level == 4 | lvl_school_log == "High" ~ "Academic",
    level == 3 | lvl_school_log == "Medium" ~ "Intermediate",
    level %in% 1:2 | lvl_school_log == "Low" ~ "Vocational",
    .default = "Unknown"
  )
})

local({
  band <- c(`1` = 5 / 60, `2` = 20 / 60, `3` = 45 / 60, `4` = 1.25, `5` = 1.5)
  answer <- as.numeric(haven::zap_labels(jq22a))
  no_device <- as.numeric(haven::zap_labels(jq8b)) %in% 0 | as.numeric(haven::zap_labels(jq9)) %in% c(0, 9999)
  case_when(answer %in% 1:5 ~ unname(band[as.character(answer)]), no_device ~ 0, .default = NA_real_)
})

