local({
  items <- cbind(sdq_e, sdq_g, sdq_l, sdq_r, sdq_v)
  scored <- if_else(rowSums(!is.na(items)) >= 3, floor(rowMeans(items, na.rm = TRUE) * 5 + 0.5), NA_real_)
  if_else(cohort == "HERMES3", scored, jsconduct)
})

