local({
  scored <- lapply(
    list(
      cbind(sdq_c, sdq_h, sdq_m, sdq_p, sdq_x),
      cbind(sdq_e, sdq_g, sdq_l, sdq_r, sdq_v),
      cbind(sdq_b, sdq_j, sdq_o, sdq_u, sdq_y),
      cbind(sdq_f, sdq_k, sdq_n, sdq_s, sdq_w)
    ),
    function(items) if_else(rowSums(!is.na(items)) >= 3, floor(rowMeans(items, na.rm = TRUE) * 5 + 0.5), NA_real_)
  )
  if_else(cohort == "HERMES3", scored[[1]] + scored[[2]] + scored[[3]] + scored[[4]], jsebdtot)
})
